#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_operation_has_a_typed_error_mapping() {
        assert_eq!(
            ServiceOperationId::ALL.len(),
            OPERATION_SPECIFIC_ERRORS.len()
        );
        for (index, operation) in ServiceOperationId::ALL.iter().copied().enumerate() {
            assert_eq!(operation as usize, index);
            for error in operation.operation_specific_errors() {
                match error {
                    OperationSpecificError::Code(code) => {
                        assert!(ErrorCode::is_registered(code.as_str()))
                    }
                    OperationSpecificError::Reason(reason) => {
                        assert!(ReasonCode::is_registered(reason.as_str()))
                    }
                }
            }
        }
    }
}
